        body: `▼ゼロから：
家の壁のコンセントに、なぜ穴が2つあるのでしょうか。
電気は「行って帰ってくる」ものだからです。行きの線と帰りの線、合わせて2本。
この一番シンプルな配電のかたちが単相2線式（たんそう2せんしき）です。
記号では 1φ2W と書きます。φ（ファイ）は相の数、W は線（wire）の数です。
第二種電気工事士の配電理論は、この2線式を出発点に、3線式・三相へと広がっていきます。
まずは「電線は2本、電圧は100V、負荷は線間につなぐ」という原型を頭に焼き付けます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 単相2線式とはどんな回路か
━━━━━━━━━━━━━━━━━━━━━━
・変圧器の二次側の巻線の両端から2本の電線を引き出した配電方式★
・2本のうち一方は必ず接地されている。これを接地側電線（中性線に相当）という★
・接地されていないほうを非接地側電線（電圧側電線）という★
・接地側の対地電圧は 0V、非接地側の対地電圧は 100V になる★
・線間電圧（2本の間の電圧）は 100V。負荷はこの2本の間に接続する
・電灯・コンセントなど、100Vで動く小容量の負荷に使う
・電線が2本で済むので、工事が最も簡単で材料費も安い

━━━━━━━━━━━━━━━━━━━━━━
🔑 接地側と非接地側の区別が工事の基本
━━━━━━━━━━━━━━━━━━━━━━
・接地側電線は白色（W）で表す。器具では接地側端子（Wの刻印、ねじが銀色）へ結線★
・非接地側電線は黒色（B）で表す。点滅器（スイッチ）は必ず非接地側に入れる★
・○ スイッチを非接地側に入れると、切ったとき器具に電圧がかからず安全
・× スイッチを接地側に入れると、切っても器具に100Vが残り感電の危険がある
・コンセントは接地側極（長いほうの穴、Wと刻印）に白線をつなぐ
・ランプレセプタクルは受金（ねじ部）に接地側の白線をつなぐ★
・この色分けは配線図問題でも実技でも必ず問われる

━━━━━━━━━━━━━━━━━━━━━━
🔑 単相2線式の電力・電流の関係
━━━━━━━━━━━━━━━━━━━━━━
・電力 P ＝ 電圧 V × 電流 I × 力率 cosθ（単相の基本式）★
・電灯や電熱器のように力率が 1 の負荷なら P ＝ V × I でよい
・電流 I ＝ P ÷（V × cosθ）で求める
・電線には行きと帰りで同じ大きさの電流が流れる（2線とも I）★
・したがって電圧降下も電力損失も、電線2本分を数える必要がある

【計算例】100V・1500Wの電熱器（力率1）の電流
　式：I ＝ P ÷ V
　代入：I ＝ 1500 ÷ 100
　答え：I ＝ 15 A
　→ 15A なので、15A分岐回路のコンセント1個をほぼ使い切る負荷になる

【図解】単相2線式の各部の電圧
　測る場所｜電圧の値｜呼び名
　非接地側と接地側の間｜100 V｜線間電圧★
　非接地側と大地の間｜100 V｜対地電圧★
　接地側と大地の間｜0 V｜接地されている
　→ 単相2線式100Vでは線間電圧と対地電圧が同じ100Vになる
　⚠ 接地側電線でも電流は流れている。電圧が0Vなだけで「電気が来ていない」わけではない

【図解】単相2線式のメリットとデメリット
　観点｜内容｜評価
　電線本数｜2本で済む｜○ 安い
　得られる電圧｜100Vの1種類だけ｜× 200V機器が使えない
　同じ電力を送るときの電流｜大きくなる｜× 電圧降下が大きい
　→ 大きな電力を送るには不向きで、住宅の主流は単相3線式に置き換わった
　⚠ 「単相2線式でも200Vが取り出せる」は誤り。二次側200Vの変圧器を使えば線間200Vにはなるが、その場合も1種類しか取り出せない

━━━━━━━━━━━━━━━━━━━━━━
🔑 単相2線式が今も使われる場面
━━━━━━━━━━━━━━━━━━━━━━
・古い住宅や小規模なアパートの引込みには、いまも単相2線式が残っている
・住宅内でも、分電盤から先の100V分岐回路は実質的に単相2線式である★
・つまり「引込みは単相3線式、分岐回路は単相2線式」という組合せが一般的★
・したがって分岐回路の電圧降下計算には、単相2線式の式 v＝2ILr を使う★
・仮設配線、屋外の小容量電源、単独の照明回路なども単相2線式で足りる
・契約容量が小さい場合は3線式にする必要がなく、材料費の面で有利になる
・○「分岐回路の電圧降下は2ILrで計算する」→ 正しい。ここを間違える受験者が多い

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・× 「接地側電線は電流が流れないので細くてよい」→ 同じ電流が流れる。太さは同じ★
・× 「点滅器は接地側電線に取り付ける」→ 非接地側に取り付ける
・○ 「接地側電線の対地電圧は0Vである」→ 正しい
・× 「単相2線式の対地電圧は線間電圧の半分」→ 半分になるのは単相3線式のほう
・計算問題では「電圧降下 v ＝ 2 I L r」の 2 の意味（往復2本分）が問われる★
・配線図問題では白線・黒線の結線先が問われる。W＝白＝接地側を機械的に思い出す

★ここだけ暗記
・単相2線式＝1φ2W。電線2本、線間100V、対地電圧100V★
・白（W）は接地側、黒（B）は非接地側。スイッチは黒（非接地側）に入れる★
・電力 P＝VIcosθ、電流 I＝P÷(Vcosθ)
・電圧降下も損失も電線2本分で数える（係数2が付く）★`,
