        body: `▼ゼロから：
いまの住宅の引込線をよく見ると、電線が3本入っています。
2本で足りるはずなのに、なぜ3本なのでしょうか。
理由は「100Vと200Vの両方を1つの引込みで使いたい」からです。
エアコンやIHクッキングヒーターは200V、照明やテレビは100V。
この2つを1組の配線でまかなうのが単相3線式（1φ3W）です。
仕組みは単純で、変圧器の二次巻線の真ん中から線を1本追加しただけです。
この「真ん中の線」が中性線であり、単相3線式の理解のすべてが中性線に集約されます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 単相3線式の構造
━━━━━━━━━━━━━━━━━━━━━━
・変圧器の二次巻線 200V の中点（真ん中）から線を引き出した方式★
・引き出した3本を、外側から順に L1（電圧線）・N（中性線）・L2（電圧線）と呼ぶ
・中性線 N はB種接地工事により接地されている★
・外側線と中性線の間＝100V、外側線どうしの間＝200V★
・中性線は必ず白色電線を使い、電力量計や分電盤でも中央に配置する
・住宅の標準的な引込方式であり、試験でも最頻出

━━━━━━━━━━━━━━━━━━━━━━
🔑 なぜ1つの引込みで100Vと200Vが取れるのか
━━━━━━━━━━━━━━━━━━━━━━
・二次巻線全体で200V、その中点を取り出すと上半分100V・下半分100V
・上半分（L1とN）から100V、下半分（L2とN）から100Vが得られる
・上下を足した両端（L1とL2）から200Vが得られる★
・L1側とL2側の100Vは、位相が互いに逆向き（180度違い）になっている★
・逆位相どうしなので、両端で見ると 100＋100＝200V になる
・○「L1-N間とL2-N間の電圧はどちらも100V」→ 正しい
・× 「L1-N間とL2-N間を足しても0Vになる」→ 逆位相の足し算で200Vになる

━━━━━━━━━━━━━━━━━━━━━━
🔑 中性線には何が流れるか
━━━━━━━━━━━━━━━━━━━━━━
・中性線に流れる電流は、L1側とL2側の電流の「差」になる★
・中性線電流 IN ＝ ∣I1 － I2∣（大きいほうから小さいほうを引く）★
・両側の負荷が等しい（平衡している）とき IN ＝ 0 になる★
・平衡していれば中性線に電流が流れないので、電力損失も電圧降下も小さい
・これが単相3線式が「効率がよい」と言われる最大の理由

【計算例】L1側20A、L2側15Aのときの中性線電流
　式：IN ＝ ∣I1 － I2∣
　代入：IN ＝ ∣20 － 15∣
　答え：IN ＝ 5 A
　→ 負荷を均等に振り分けるほど中性線電流は小さくなる

【図解】単相3線式の電圧のとり方
　測る2点｜電圧｜用途
　L1と中性線｜100 V★｜照明・一般コンセント
　L2と中性線｜100 V★｜照明・一般コンセント
　L1とL2｜200 V★｜エアコン・IH・電気温水器
　→ 中性線と大地の間は0V、外側線と大地の間は100V（対地電圧100V）
　⚠ 三相200Vと違い、単相3線式200Vの対地電圧は100V。絶縁抵抗の判定でここが効いてくる

【図解】単相2線式との比較（同じ電力を送るとき）
　項目｜単相2線式100V｜単相3線式100/200V
　電線本数｜2本｜3本
　取り出せる電圧｜100Vのみ｜100Vと200V★
　電線1本の電流｜大きい｜約半分になる★
　→ 電流が半分になるので電圧降下も小さく、電線を細くできる
　⚠ 「3線式は電線が1本増えるので不利」は誤り。総電線量はむしろ少なくて済む

━━━━━━━━━━━━━━━━━━━━━━
🔑 単相3線式の電力の求め方
━━━━━━━━━━━━━━━━━━━━━━
・単相3線式の全電力は、L1側の100V負荷とL2側の100V負荷と200V負荷の合計★
・100V負荷の電力 ＝ 100 × その側の100V負荷電流
・200V負荷の電力 ＝ 200 × 200V負荷の電流
・全体の電力は、それぞれを単純に足し算すればよい（力率1のとき）★
・不平衡でも、電力の合計は各負荷の電力の和で変わらない

【計算例】L1-N間に1000W、L2-N間に600W、L1-L2間に2000W
　式：全電力 ＝ 各負荷の電力の合計
　代入：1000 ＋ 600 ＋ 2000
　答え：3600 W
　→ このとき L1 の線電流は 100V負荷10A と 200V負荷10A の合成になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・× 「中性線は電流が流れないので細くてよい」→ 不平衡時に流れる。同じ太さにする★
・× 「中性線に過電流遮断器（ヒューズ）を設けてよい」→ 中性線には設けてはならない★
・○ 「中性線にはB種接地工事が施されている」→ 正しい
・× 「L1-N間とL2-N間は同相である」→ 逆位相（180度差）である
・計算問題は「中性線電流を求めよ」「平衡負荷での電圧降下」が定番★

★ここだけ暗記
・単相3線式＝1φ3W。外側線と中性線で100V、外側線どうしで200V★
・中性線電流 IN＝∣I1－I2∣。平衡なら0A★
・中性線は白色・B種接地・過電流遮断器を設けてはならない★
・対地電圧は100V（200V回路でも対地は100V）★`,
