入口では100Vあったのに、出口では97Vしかない。この差3Vが電圧降下です。
電圧が下がると、電球は暗くなり、電動機は力が出ず、機器の寿命も縮みます。
だから法令や内線規程は「電圧降下は何パーセント以内」と上限を決めています。
