        title: '接地工事の種類と接地抵抗値',
        emoji: '🌍',
        body: `▼ゼロから：
洗濯機のアース線を、なぜコンセントの下の端子につなぐのでしょうか。
機器の中で漏電が起きたとき、電気が人ではなく大地へ逃げるようにするためです。
この「電気を大地へ逃がす道」をつくるのが接地工事です。
接地工事にはA種・B種・C種・D種の4種類があり、
それぞれ対象となる設備と、必要な接地抵抗値が決まっています。
数値は毎年出題される暗記項目です。表で一気に覚えてしまいましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 接地工事の目的
━━━━━━━━━━━━━━━━━━━━━━
・漏電したときの感電を防ぐ（人体より抵抗の低い道をつくる）★
・漏電遮断器を確実に動作させる（地絡電流の通り道をつくる）★
・高圧と低圧が混触したときの低圧側の電位上昇を抑える（B種）★
・雷や異常電圧から機器を保護する★
・機器の金属製外箱の電位を大地と同じに保つ★
・○「接地工事の主目的は感電防止」→ 正しい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 4種類の接地工事
━━━━━━━━━━━━━━━━━━━━━━
・A種接地工事：高圧・特別高圧用機器の金属製外箱、避雷器など★
・B種接地工事：高圧と低圧を結合する変圧器の低圧側中性点★
・C種接地工事：300Vを超える低圧用機器の金属製外箱など★
・D種接地工事：300V以下の低圧用機器の金属製外箱など★
・第二種の実務で最も多く扱うのはD種接地工事★
・A種とC種は10Ω以下、D種は100Ω以下★
・B種だけは計算で求める（150÷1線地絡電流）★

【図解】接地工事の種類と接地抵抗値
　種類｜接地抵抗値｜対象
　A種｜10 Ω以下★｜高圧・特別高圧機器
　C種｜10 Ω以下★｜300 Vを超える低圧機器
　D種｜100 Ω以下★｜300 V以下の低圧機器
　→ A種とC種はどちらも10Ω以下。数字が同じなので覚えやすい
　⚠ B種は固定値ではなく計算値。150÷1線地絡電流で求める

━━━━━━━━━━━━━━━━━━━━━━
🔑 C種・D種の緩和規定
━━━━━━━━━━━━━━━━━━━━━━
・地絡を生じたとき0.5秒以内に自動的に電路を遮断する装置を施設した場合★
・C種接地工事：500Ω以下に緩和される★
・D種接地工事：500Ω以下に緩和される★
・つまり漏電遮断器を設ければ、接地抵抗の要求が緩くなる★
・地面が岩盤などで接地抵抗を下げにくい場所で有効な規定★
・○「漏電遮断器を施設すればD種は500Ω以下でよい」→ 正しい★

【図解】C種・D種の緩和
　種類｜原則｜0.5秒以内に遮断する装置がある場合
　C種｜10 Ω以下★｜500 Ω以下★
　D種｜100 Ω以下★｜500 Ω以下★
　→ どちらも緩和後は同じ500Ω以下になる
　⚠ 緩和されるのは「0.5秒以内」の遮断装置。1秒では緩和されない

━━━━━━━━━━━━━━━━━━━━━━
🔑 どの機器にどの接地工事を施すか
━━━━━━━━━━━━━━━━━━━━━━
・100Vの洗濯機・冷蔵庫・電子レンジの金属製外箱 → D種★
・200Vのエアコン室外機・IHの金属製外箱 → D種（300V以下のため）★
・金属管工事の金属管、金属可とう電線管、金属線ぴ → D種（300V以下）★
・使用電圧400Vの機器の金属製外箱 → C種★
・高圧受電設備の高圧機器の金属製外箱 → A種★
・避雷器の接地 → A種★
・○「200V回路の機器の外箱にはD種接地工事」→ 300V以下なので正しい★

【図解】接地工事の対象の判定
　対象｜使用電圧｜接地工事
　一般家庭の電気機器｜100〜200 V★｜D種★
　400 V級の低圧機器｜300 V超★｜C種★
　高圧機器・避雷器｜高圧以上★｜A種★
　→ 判定は「300Vを超えるかどうか」が分かれ目
　⚠ 200Vは300V以下なのでD種。C種と間違えやすい

━━━━━━━━━━━━━━━━━━━━━━
🔑 B種接地工事の抵抗値
━━━━━━━━━━━━━━━━━━━━━━
・原則：150 ÷ 1線地絡電流（Ω）以下★
・高圧と低圧が混触したとき1秒を超え2秒以内に遮断する装置があれば 300 ÷ 地絡電流★
・1秒以内に遮断する装置があれば 600 ÷ 地絡電流★
・遮断が速いほど、許される接地抵抗が大きくなる★
・150という数字は「低圧側の対地電圧を150V以下に抑える」ことに由来する★

【計算例】1線地絡電流が5AのときのB種接地抵抗（原則）
　式：接地抵抗 ＝ 150 ÷ 1線地絡電流
　代入：150 ÷ 5
　答え：30 Ω以下
　→ 1秒以内に遮断する装置があれば 600 ÷ 5 ＝ 120Ω以下でよい

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・× 「D種接地工事の接地抵抗は10Ω以下」→ 100Ω以下★
・× 「C種接地工事は300V以下の機器に施す」→ 300Vを超える機器★
・○ 「A種とC種はともに10Ω以下」→ 正しい★
・× 「D種の緩和は1秒以内の遮断装置」→ 0.5秒以内★
・出題は種類と抵抗値の組合せ、および対象設備の判定が中心★

★ここだけ暗記
・A種10Ω以下、B種150÷地絡電流、C種10Ω以下、D種100Ω以下★
・C種・D種は0.5秒以内の遮断装置があれば500Ω以下★
・C種は300V超、D種は300V以下★
・B種は変圧器の低圧側中性点。混触時の電位上昇を抑える★`,
