これが漏えい電流です。
正常な状態ならごく小さく、人体にも影響しません。
しかし絶縁が劣化すると漏えい電流が増え、感電や火災の危険が高まります。
そこで「絶縁抵抗が測れない場合は、漏えい電流が1mA以下であればよい」という
