需要率は「全部を同時には使わない」ことを表す係数でした。
これを掛けることで、幹線を必要以上に太くせずに済みます。
ただし掛ける順序を間違えると答えが変わってしまいます。
本節では、需要率を含む幹線計算の型を、具体例で固めます。

━━━━━━━━━━━━━━━━━━━━━━
