・住宅や一般の低圧回路では高感度形（30mA）を使う★
・人体保護を目的とする場合は15mA以下のものを使う★
・漏電火災の防止を目的とする場合は100mA〜数百mAのものを使う★

━━━━━━━━━━━━━━━━━━━━━━
