・A種・B種の接地線を人が触れるおそれのある場所に施設する場合★
・接地極の上端から地下75cmまでと、地表上2mまでの部分を保護する★
・保護には合成樹脂管（厚さ2mm以上）などを用いる★
・金属管で保護すると、そこに誘導電流が流れるため使わない★
