━━━━━━━━━━━━━━━━━━━━━━
・複数の機器の接地を1つの接地極にまとめることを共用接地という★
・共用すると接地抵抗が下がり、電位差もなくなるので安全性が高まる★
・一方、通信機器や医療機器では、ノイズを避けるため専用の接地を設けることがある★
