        id: 'd2-ha-69',
        title: '力率改善の総合計算',
        emoji: '📘',
        body: `▼ゼロから：
力率が悪いと電流が増え、電線が太くなり、損失も増える。
そこで進相コンデンサを入れて力率を改善する。
ここまでは学びました。では「どのくらいのコンデンサを入れればよいか」。
これを求めるには、有効電力・無効電力・皮相電力の三角形を使います。
第二種の範囲では深い計算は問われませんが、
考え方を知っておくと力率の問題全般に強くなります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 電力の三角形
━━━━━━━━━━━━━━━━━━━━━━
・有効電力 P（W）：実際に仕事をする電力★
・無効電力 Q（var）：電源と負荷を往復するだけの電力★
・皮相電力 S（V・A）：電圧と電流の積★
・関係は S の2乗 ＝ P の2乗 ＋ Q の2乗★
・力率 cosθ ＝ P ÷ S★
・無効率 sinθ ＝ Q ÷ S★

【計算例】有効電力8kW、力率0.8のときの皮相電力と無効電力
　式：S ＝ P ÷ cosθ
　代入：8 ÷ 0.8 ＝ 10 kV・A
　式：Q の2乗 ＝ S の2乗 － P の2乗
　代入：Q の2乗 ＝ 100 － 64 ＝ 36
　答え：Q ＝ 6 kvar
　→ 3対4対5の直角三角形の関係になっている

━━━━━━━━━━━━━━━━━━━━━━
🔑 コンデンサ容量の求め方
━━━━━━━━━━━━━━━━━━━━━━
・必要な容量 ＝ 改善前の無効電力 － 改善後の無効電力★
・改善後の無効電力は、目標の力率から計算する★
・有効電力 P は改善の前後で変わらない★
・力率1まで改善するなら、必要な容量は改善前の無効電力そのもの★
・実務では力率1にはせず、0.95程度を目標にすることが多い★

【計算例】有効電力8kW、力率0.8を力率1.0に改善する
　式：必要な容量 ＝ 改善前のQ － 改善後のQ
　代入：6 － 0 ＝ 6 kvar
　答え：6 kvar のコンデンサが必要
　→ 力率1にすると皮相電力は10kV・Aから8kV・Aに減る

【計算例】有効電力8kW、力率0.8を力率0.95に改善する
　式：改善後のS ＝ P ÷ 0.95 ＝ 8 ÷ 0.95 ＝ 約8.42 kV・A
　式：改善後のQ の2乗 ＝ 8.42 の2乗 － 8 の2乗 ＝ 70.9 － 64 ＝ 6.9
　代入：改善後のQ ＝ 約2.63 kvar
　答え：必要な容量 ＝ 6 － 2.63 ＝ 約3.4 kvar
　→ 0.95まででよければ、コンデンサは約半分で済む

━━━━━━━━━━━━━━━━━━━━━━
🔑 改善による効果の計算
━━━━━━━━━━━━━━━━━━━━━━
・線電流 ＝ 皮相電力 ÷ 電圧（三相なら √3 × 電圧）★
・皮相電力が減れば、線電流も同じ割合で減る★
・電力損失は電流の2乗に比例するので、大きく減る★
・電圧降下は電流に比例するので、電流と同じ割合で減る★

【計算例】三相200V、皮相電力10kV・Aが8kV・Aに減ったときの線電流
　式：I ＝ S ÷（√3 × V）
　代入：改善前 I ＝ 10000 ÷（1.73 × 200）＝ 約28.9 A
　代入：改善後 I ＝ 8000 ÷（1.73 × 200）＝ 約23.1 A
　答え：線電流は約28.9Aから約23.1Aへ（約80％に減少）
　→ 損失は 0.8 × 0.8 ＝ 0.64倍（36％減）になる

【図解】力率改善の効果
　項目｜改善前（0.8）｜改善後（1.0）
　皮相電力｜10 kV・A★｜8 kV・A★
　線電流｜約28.9 A★｜約23.1 A★
　電力損失｜1.00｜0.64★
　→ 有効電力8kWは変わらないまま、電流と損失だけが減る
　⚠ 力率を改善しても有効電力（実際の仕事）は増えも減りもしない

━━━━━━━━━━━━━━━━━━━━━━
🔑 力率の代表的な値
━━━━━━━━━━━━━━━━━━━━━━
・白熱電球・電熱器などの抵抗負荷：力率1.0★
・三相誘導電動機（全負荷運転）：0.8〜0.9程度★
・三相誘導電動機（軽負荷運転）：0.5以下まで落ちることもある★
・蛍光灯（安定器付き）：0.5〜0.6程度（コンデンサ内蔵で0.9程度）★
・軽負荷の電動機ほど力率が悪くなるのが特徴★
・○「電動機は軽負荷ほど力率が悪い」→ 正しい★
・したがって、容量に余裕をもたせすぎた電動機は力率が悪化する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・× 「力率を改善すると有効電力が増える」→ 変わらない★
・× 「コンデンサ容量の単位はkW」→ kvar★
・○ 「S²＝P²＋Q² の関係が成り立つ」→ 正しい★
・× 「力率改善で電圧降下は変わらない」→ 電流が減るので小さくなる★
・出題は皮相電力・無効電力の計算と、改善の効果の判定が中心★

★ここだけ暗記
・S²＝P²＋Q²、cosθ＝P÷S★
・必要なコンデンサ容量 ＝ 改善前のQ － 改善後のQ（単位kvar）★
・力率改善で減るのは 皮相電力・線電流・損失・電圧降下★
・有効電力は改善しても変わらない★`,
