そのために引込口の近くに設けるのが引込口装置です。
住宅では分電盤の主幹漏電遮断器がこれを兼ねています。
しかし、複数の建物がある場合や、離れた小屋に電気を送る場合など、
引込口装置を省略できる条件も定められています。

